void reverse_string(char str[]) {
    int len = strlen(str);
    for (int i = 0; i < len / 2; i++) {
        char temp = str[i];
        str[i] = str[len - 1 - i];
        str[len - 1 - i] = temp;
    }
}

int main() {
    char str[] = "Hello World";
    printf("Original: %s\n", str);
    reverse_string(str);
    printf("Reversed: %s\n", str);
    return 0;
}

#include <stdio.h>
#include <stdbool.h>
#define MAX_SIZE 100

typedef struct {
    int data[MAX_SIZE];
    int top;
} Stack;

void init_stack(Stack *s) {
    s->top = -1;
}

bool is_empty(Stack *s) {
    return s->top == -1;
}

bool is_full(Stack *s) {
    return s->top == MAX_SIZE - 1;
}

bool push(Stack *s, int value) {
    if (is_full(s)) return false;
    s->data[++s->top] = value;
    return true;
}

bool pop(Stack *s, int *value) {
    if (is_empty(s)) return false;
    *value = s->data[s->top--];
    return true;
}

bool peek(Stack *s, int *value) {
    if (is_empty(s)) return false;
    *value = s->data[s->top];
    return true;
}

